B.asF=s(["\u0631\u062a\u0651\u0628 \u062d\u0642\u064a\u0628\u062a\u0643 \u0648\u062c\u062f\u0648\u0644\u0643 \u0645\u0646 \u0623\u0648\u0644 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u060c \u0641\u0627\u0644\u062a\u0646\u0638\u064a\u0645 \u0646\u0635\u0641 \u0627\u0644\u0646\u062c\u0627\u062d.","\u0636\u0639 \u0647\u062f\u0641\u0627\u064b \u0635\u063a\u064a\u0631\u0627\u064b \u0644\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0648\u0627\u0643\u062a\u0628\u0647 \u0641\u064a \u062f\u0641\u062a\u0631\u0643.","\u0627\u062d\u0636\u0631 \u0645\u0628\u0643\u0631\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u0631\u0633\u0629\u060c \u0641\u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0647\u064a\u0651\u0626 \u0630\u0647\u0646\u0643 \u0644\u0644\u064a\u0648\u0645.","\u0627\u0628\u062f\u0623 \u0623\u0633\u0628\u0648\u0639\u0643 \u0628\u0627\u0628\u062a\u0633\u0627\u0645\u0629 \u0648\u0633\u0644\u0627\u0645 \u0639\u0644\u0649 \u0645\u0639\u0644\u0645\u064a\u0643 \u0648\u0632\u0645\u0644\u0627\u0626\u0643."],t.s)
B.aeP=s(["\u0631\u0627\u062c\u0639 \u062f\u0631\u0648\u0633 \u0627\u0644\u0623\u0645\u0633 \u0644\u0645\u062f\u0629 \u0639\u0634\u0631 \u062f\u0642\u0627\u0626\u0642\u060c \u0641\u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629 \u062a\u062b\u0628\u0651\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629.","\u0627\u0633\u0623\u0644 \u0645\u0639\u0644\u0645\u0643 \u0639\u0646 \u0623\u064a \u0646\u0642\u0637\u0629 \u0644\u0645 \u062a\u0641\u0647\u0645\u0647\u0627\u060c \u0641\u0627\u0644\u0633\u0624\u0627\u0644 \u0644\u0627 \u064a\u0639\u064a\u0628.","\u0627\u0634\u0631\u0628 \u0627\u0644\u0645\u0627\u0621 \u0628\u0627\u0646\u062a\u0638\u0627\u0645\u060c \u0641\u0627\u0644\u062f\u0645\u0627\u063a \u064a\u0639\u0645\u0644 \u0623\u0641\u0636\u0644 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u062c\u0633\u0645\u0643 \u0645\u0631\u062a\u0648\u064a\u0627\u064b.","\u0627\u0643\u062a\u0628 \u0627\u0644\u0648\u0627\u062c\u0628 \u0641\u064a \u064a\u0648\u0645\u0647 \u0648\u0644\u0627 \u062a\u0624\u062c\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u064a\u0644."],t.s)
B.apr=s(["\u0627\u0642\u0631\u0623 \u0635\u0641\u062d\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0643\u062a\u0627\u0628 \u062e\u0627\u0631\u062c\u064a \u064a\u0648\u0645\u064a\u0627\u064b\u060c \u0648\u0633\u062a\u062a\u0641\u0627\u062c\u0623 \u0628\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0628\u0639\u062f \u0634\u0647\u0631.","\u0630\u0627\u0643\u0631 \u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0635\u0639\u0628\u0629 \u0623\u0648\u0644\u0627\u064b \u0648\u0623\u0646\u062a \u0646\u0634\u064a\u0637\u060c \u062b\u0645 \u0627\u0644\u0623\u0633\u0647\u0644.","\u062e\u0630 \u0627\u0633\u062a\u0631\u0627\u062d\u0629 \u0642\u0635\u064a\u0631\u0629 \u0643\u0644 \u0646\u0635\u0641 \u0633\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0645\u0630\u0627\u0643\u0631\u0629 \u0644\u062a\u062c\u062f\u062f \u062a\u0631\u0643\u064a\u0632\u0643.","\u0633\u0627\u0639\u062f \u0632\u0645\u064a\u0644\u0627\u064b \u0641\u064a \u0641\u0647\u0645 \u062f\u0631\u0633\u060c \u0641\u0634\u0631\u062d\u0643 \u0644\u0647 \u064a\u0642\u0648\u0651\u064a \u0641\u0647\u0645\u0643 \u0623\u0646\u062a."],t.s)
B.amu=s(["\u0646\u0645\u0652 \u0645\u0628\u0643\u0631\u0627\u064b\u060c \u0641\u0627\u0644\u0646\u0648\u0645 \u0627\u0644\u0643\u0627\u0641\u064a \u064a\u0631\u0641\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0648\u0627\u0644\u062d\u0641\u0638.","\u0627\u0643\u062a\u0628 \u0645\u0644\u062e\u0635\u0627\u064b \u0628\u062e\u0637 \u064a\u062f\u0643 \u0644\u0644\u062f\u0631\u0633\u060c \u0641\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u062a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u0627\u0644\u062a\u0630\u0643\u0651\u0631.","\u0644\u0627 \u062a\u0642\u0627\u0631\u0646 \u0646\u0641\u0633\u0643 \u0628\u063a\u064a\u0631\u0643\u060c \u0642\u0627\u0631\u0646 \u0646\u0641\u0633\u0643 \u0628\u0645\u0627 \u0643\u0646\u062a \u0639\u0644\u064a\u0647 \u0623\u0645\u0633.","\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0646\u0638\u0627\u0641\u0629 \u0645\u0642\u0639\u062f\u0643 \u0648\u0643\u062a\u0628\u0643\u060c \u0641\u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u0631\u062a\u0628 \u064a\u0639\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0631\u0643\u064a\u0632."],t.s)
B.apq=s(["\u0631\u0627\u062c\u0639 \u0645\u0627 \u062f\u0631\u0633\u062a\u0647 \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0642\u0628\u0644 \u0627\u0644\u0639\u0637\u0644\u0629 \u062d\u062a\u0649 \u0644\u0627 \u062a\u0646\u0633\u0627\u0647.","\u0623\u0646\u062c\u0632 \u0648\u0627\u062c\u0628\u0627\u062a\u0643 \u0642\u0628\u0644 \u0627\u0644\u0639\u0637\u0644\u0629 \u0644\u062a\u0633\u062a\u0645\u062a\u0639 \u0628\u0648\u0642\u062a\u0643 \u0628\u0631\u0627\u062d\u0629 \u0628\u0627\u0644.","\u062a\u0630\u0643\u0651\u0631 \u0623\u0646 \u062a\u0634\u0643\u0631 \u0645\u0639\u0644\u0645\u064a\u0643 \u0639\u0644\u0649 \u062c\u0647\u062f\u0647\u0645\u060c \u0643\u0644\u0645\u0629 \u0637\u064a\u0628\u0629 \u062a\u0641\u0631\u062d\u0647\u0645.","\u062d\u062f\u062f \u0645\u0627 \u0633\u062a\u0631\u0627\u062c\u0639\u0647 \u0641\u064a \u0627\u0644\u0639\u0637\u0644\u0629 \u0644\u064a\u0643\u0648\u0646 \u0623\u0633\u0628\u0648\u0639\u0643 \u0627\u0644\u0642\u0627\u062f\u0645 \u0623\u0633\u0647\u0644."],t.s)
B.anC=s(["\u0627\u063a\u062a\u0646\u0645 \u064a\u0648\u0645 \u0627\u0644\u062c\u0645\u0639\u0629 \u0628\u0635\u0644\u0627\u0629 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0648\u0642\u0631\u0627\u0621\u0629 \u0645\u0627 \u062a\u064a\u0633\u0651\u0631 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646.","\u0627\u0642\u0636\u0650 \u0648\u0642\u062a\u0627\u064b \u0645\u0639 \u0623\u0647\u0644\u0643\u060c \u0641\u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0633\u0646\u062f\u0643 \u0627\u0644\u0623\u0648\u0644.","\u0627\u0642\u0631\u0623 \u0643\u062a\u0627\u0628\u0627\u064b \u0623\u0648 \u0642\u0635\u0629 \u0645\u0641\u064a\u062f\u0629 \u0627\u0644\u064a\u0648\u0645 \u0628\u062f\u0644 \u0642\u0636\u0627\u0621 \u0627\u0644\u0648\u0642\u062a \u0643\u0644\u0647 \u0623\u0645\u0627\u0645 \u0627\u0644\u0634\u0627\u0634\u0629.","\u062a\u0635\u062f\u0651\u0642 \u0648\u0644\u0648 \u0628\u0634\u064a\u0621 \u0628\u0633\u064a\u0637\u060c \u0641\u0627\u0644\u0639\u0637\u0627\u0621 \u064a\u064f\u0633\u0639\u062f \u0627\u0644\u0642\u0644\u0628."],t.s)
